const $=selector=>document.querySelector(selector);
let photos=[],categories=[],editing=null,uploadId=null,deleteId=null,previewUrl=null;
async function api(action,method='GET',data){const response=await fetch(`/api/admin?action=${action}`,{method,credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined,cache:'no-store'});const result=await response.json().catch(()=>({error:'ไม่สามารถเชื่อมต่อระบบได้'}));if(!response.ok){if(response.status===401&&action!=='login')showLogin();throw Error(result.error||'เกิดข้อผิดพลาด')}return result}
function node(tag,text,className){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(className)el.className=className;return el}
function showLogin(){$('#dashboard').hidden=true;$('#login-panel').hidden=false;$('#boot-status').hidden=true}
function option(value,label){const el=node('option',label);el.value=value;return el}
async function refresh(message=''){const data=await api('data');photos=data.photos;categories=data.categories;$('#dashboard').hidden=false;$('#login-panel').hidden=true;$('#boot-status').hidden=true;const filter=$('#filter-category'),selected=filter.value;filter.replaceChildren(option('all','ทุกหมวดหมู่'),...categories.map(c=>option(c.key,c.label)));filter.value=categories.some(c=>c.key===selected)?selected:'all';render();$('#status').textContent=message}
function render(){const active=photos.filter(p=>!p.deleted_at);$('#stat-total').textContent=active.length;$('#stat-visible').textContent=active.filter(p=>p.visible).length;$('#stat-hidden').textContent=active.filter(p=>!p.visible).length;const search=$('#search').value.trim().toLowerCase(),category=$('#filter-category').value,status=$('#filter-status').value;const filtered=photos.filter(p=>(status==='trash'?p.deleted_at:!p.deleted_at)&&(category==='all'||p.category===category)&&(!search||p.title.toLowerCase().includes(search))&&(status!=='visible'||p.visible)&&(status!=='hidden'||!p.visible));const grid=$('#admin-grid');grid.replaceChildren();for(const p of filtered){const card=node('article',undefined,'admin-card'),img=node('img');img.src=p.thumb_url;img.alt=p.title;img.loading='lazy';const content=node('div');content.append(node('span',p.deleted_at?'ถังขยะ':p.visible?'เผยแพร่':'ซ่อน',`badge ${p.deleted_at?'trash':p.visible?'':'hidden'}`),node('h3',p.title),node('p',`${p.category_label} · ลำดับ ${p.sort_order}`));const actions=node('div',undefined,'card-actions');if(p.deleted_at){const restore=node('button','กู้คืน');restore.onclick=async()=>{restore.disabled=true;try{await api('restore','POST',{id:p.id});await refresh('กู้คืนผลงานแล้ว')}catch(e){$('#status').textContent=e.message;restore.disabled=false}};actions.append(restore)}else{const edit=node('button','แก้ไข');edit.onclick=()=>openEditor(p);const remove=node('button','ลบ','danger');remove.onclick=()=>{deleteId=p.id;$('#delete-name').textContent=p.title;$('#delete-error').textContent='';$('#delete-dialog').showModal()};actions.append(edit,remove)}content.append(actions);card.append(img,content);grid.append(card)}$('#empty-state').hidden=filtered.length>0}
function openEditor(photo=null){editing=photo;uploadId=null;const form=$('#photo-form');form.reset();form.elements.id.value=photo?.id||'';form.elements.title.value=photo?.title||'';form.elements.sort_order.value=photo?.sort_order??(photos.reduce((max,p)=>Math.max(max,p.sort_order),-1)+1);form.elements.visible.checked=photo?.visible??true;form.elements.category.replaceChildren(...categories.map(c=>option(c.key,c.label)));if(photo)form.elements.category.value=photo.category;$('#editor-title').textContent=photo?'แก้ไขผลงาน':'เพิ่มผลงาน';$('#save-error').textContent='';$('#edit-preview').hidden=!photo;if(photo)$('#edit-preview').src=photo.thumb_url;$('#editor').showModal()}
$('#photo-form').elements.image.addEventListener('change',event=>{const file=event.target.files[0];if(previewUrl)URL.revokeObjectURL(previewUrl);if(file){previewUrl=URL.createObjectURL(file);$('#edit-preview').src=previewUrl;$('#edit-preview').hidden=false}});
async function prepareImage(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('รองรับเฉพาะ JPG, PNG และ WebP');if(file.size>20*1024*1024)throw Error('กรุณาใช้ไฟล์ขนาดไม่เกิน 20 MB');const bitmap=await createImageBitmap(file);if(bitmap.width*bitmap.height>40000000){bitmap.close();throw Error('ขนาดรูปใหญ่เกินไป กรุณาลดความละเอียด')};const ratio=Math.min(1,1800/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const data=canvas.toDataURL('image/webp',.86).split(',')[1];if(data.length>4000000)throw Error('รูปนี้มีขนาดใหญ่เกินไป กรุณาลดขนาดก่อน');return data}
$('#photo-form').addEventListener('submit',async event=>{event.preventDefault();const button=$('#save-photo'),form=event.target;button.disabled=true;$('#save-error').textContent='';try{const file=form.elements.image.files[0];if(file&&!uploadId){button.textContent='กำลังอัปโหลดรูป…';const upload=await api('upload','POST',{image:await prepareImage(file)});uploadId=upload.id}if(!editing&&!uploadId)throw Error('กรุณาเลือกรูปผลงาน');button.textContent='กำลังบันทึก…';await api('photo',editing?'PUT':'POST',{id:editing?.id,title:form.elements.title.value,category:form.elements.category.value,sort_order:Number(form.elements.sort_order.value),visible:form.elements.visible.checked,upload_id:uploadId});$('#editor').close();await refresh('บันทึกผลงานแล้ว หน้าเว็บไซต์จะใช้ข้อมูลล่าสุด')}catch(e){$('#save-error').textContent=e.message}finally{button.disabled=false;button.textContent='บันทึกผลงาน'}});
$('#login-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;$('#login-error').textContent='';try{await api('login','POST',Object.fromEntries(new FormData(event.target)));event.target.reset();await refresh()}catch(e){$('#login-error').textContent=e.message}finally{button.disabled=false}});
$('#logout').onclick=async()=>{try{await api('logout','POST',{});showLogin()}catch(e){$('#status').textContent=e.message}};
$('#add-photo').onclick=()=>openEditor();['search','filter-category','filter-status'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',render));
document.querySelectorAll('[data-close]').forEach(button=>button.onclick=()=>$('#'+button.dataset.close).close());
$('#delete-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.target.querySelector('button[type=submit]');button.disabled=true;try{await api('photo','DELETE',{id:deleteId});$('#delete-dialog').close();await refresh('ย้ายผลงานไปถังขยะแล้ว')}catch(e){$('#delete-error').textContent=e.message}finally{button.disabled=false}});
function renderCategories(){const list=$('#category-list');list.replaceChildren();for(const c of categories){const form=node('form',undefined,'category-row'),input=node('input'),button=node('button','บันทึกชื่อ');input.value=c.label;input.required=true;input.maxLength=80;input.setAttribute('aria-label','ชื่อหมวดหมู่ '+c.label);button.type='submit';form.append(input,button);form.onsubmit=async event=>{event.preventDefault();button.disabled=true;try{await api('category','PUT',{key:c.key,label:input.value});await refresh('เปลี่ยนชื่อหมวดหมู่แล้ว');renderCategories()}catch(e){$('#category-error').textContent=e.message}finally{button.disabled=false}};list.append(form)}}
$('#categories-open').onclick=()=>{renderCategories();$('#category-error').textContent='';$('#categories-dialog').showModal()};
$('#category-create').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;try{await api('category','POST',{label:event.target.elements.label.value});event.target.reset();await refresh('เพิ่มหมวดหมู่แล้ว');renderCategories()}catch(e){$('#category-error').textContent=e.message}finally{button.disabled=false}};
$('#password-open').onclick=()=>{$('#password-form').reset();$('#password-error').textContent='';$('#password-dialog').showModal()};
$('#password-form').onsubmit=async event=>{event.preventDefault();const form=event.target,button=form.querySelector('button[type=submit]');button.disabled=true;try{if(form.elements.password.value!==form.elements.confirm.value)throw Error('รหัสผ่านใหม่ทั้งสองช่องไม่ตรงกัน');await api('password','POST',{current:form.elements.current.value,password:form.elements.password.value});$('#password-dialog').close();showLogin();$('#login-error').textContent='เปลี่ยนรหัสผ่านแล้ว กรุณาเข้าสู่ระบบใหม่'}catch(e){$('#password-error').textContent=e.message}finally{button.disabled=false}};
api('session').then(()=>refresh()).catch(e=>{showLogin();if(e.message!=='กรุณาเข้าสู่ระบบ')$('#login-error').textContent=e.message});
